def probe(u, case):
    t_E = 10.0
    t_F = 20.0
    t_M = 40.0
    t_N = 53.0
    m = 2.0

    def y_of_t(t):
        if t <= t_F:
            return 4.0 * t - 26.0
        elif t <= t_M:
            dt = t - t_F
            return 54.0 + 4.0 * dt - 0.15 * dt * dt
        else:
            return -2.0 * t + 140.0

    def v_of_t(t):
        if t <= t_F:
            return 4.0
        elif t <= t_M:
            return 4.0 - 0.3 * (t - t_F)
        else:
            return -2.0

    t = t_E + u * (t_N - t_E)

    y = y_of_t(t)
    v = v_of_t(t)
    p = m * v

    h = 1e-4
    t_minus = t - h
    t_plus = t + h
    if t_minus < t_E:
        t_minus = t_E
    if t_plus > t_N:
        t_plus = t_N

    if t_plus > t_minus:
        a = (v_of_t(t_plus) - v_of_t(t_minus)) / (t_plus - t_minus)
    else:
        a = 0.0

    return {
        "u": u,
        "t": t,
        "y": y,
        "v": v,
        "a": a,
        "p": p
    }
